begin;
do $$ begin if current_setting('team_link.test_environment',true) is distinct from 'isolated' then raise exception 'Isolated fixture required';end if;end $$;
create function pg_temp.graph_assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end $$;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();pid uuid;private_pid uuid;vid uuid;rid uuid;cid uuid;payload jsonb;s jsonb;denied boolean;weight smallint;
begin
 insert into auth.users(id)values(a),(b),(c);
 insert into public.profiles(id,full_name,email,skills,interests)values(a,'Grafo ator','never-expose-a@example.test',array['JS'],array['React']),(b,'Grafo candidato','never-expose-b@example.test',array['JS'],array['React']),(c,'Grafo ponte','never-expose-c@example.test',array['Java'],array['Java']);
 insert into public.projects(owner_id,title,slug,category,short_description,description,status,visibility) values(a,'Grafo público','graph-'||a,'Tecnologia','Teste','Teste','open','public') returning id into pid;
 insert into public.projects(owner_id,title,slug,category,short_description,description,status,visibility) values(c,'Hidden secret project','hidden-graph-'||c,'Tecnologia','Teste','Teste','open','private') returning id into private_pid;
 insert into public.project_vacancies(project_id,title,skills,positions,open)values(pid,'Grafo vaga',array['JS'],2,true) returning id into vid;
 select id into rid from public.conceitos_vinculos where vacancy_id=vid and tipo='requirement' limit 1;
 select conceito_id into cid from public.conceitos_vinculos where id=rid;
 perform pg_temp.graph_assert(cid is not null,'existing canonical catalog is reused');
 insert into public.friendships(user_low,user_high,requester_id,state)values(least(a,c),greatest(a,c),a,'accepted'),(least(c,b),greatest(c,b),c,'accepted');
 perform set_config('request.jwt.claim.sub',a::text,true);execute 'set local role authenticated';
 s:=public.get_recommendation_context('friends');
 perform pg_temp.graph_assert(jsonb_array_length(s->'friends')=0,'third-party friendships are absent by default');
 perform pg_temp.graph_assert(s::text not like '%never-expose%' and s::text not like '%Hidden secret project%' and not(s->'people'->0?'email'),'no private email or inaccessible project');
 perform pg_temp.graph_assert(jsonb_array_length(s->'people')<=121 and jsonb_array_length(s->'projects')<=48,'bounded data context');
 insert into public.graph_preferences(user_id,share_connections)values(a,false)on conflict(user_id)do update set share_connections=excluded.share_connections;
 insert into public.graph_preferences(user_id,share_connections)values(a,true)on conflict(user_id)do update set share_connections=excluded.share_connections;
 perform pg_temp.graph_assert((select share_connections from public.graph_preferences where user_id=a),'own preference upsert works');
 denied:=false;begin insert into public.graph_preferences(user_id,share_connections)values(b,true);exception when insufficient_privilege then denied:=true;end;perform pg_temp.graph_assert(denied,'cannot opt in another person');
 denied:=false;begin perform public.get_recommendation_context('collaborators',private_pid);exception when insufficient_privilege then denied:=true;end;perform pg_temp.graph_assert(denied,'ID manipulation cannot open another project context');
 denied:=false;begin perform public.graph_requirement_weights(private_pid,'[]');exception when insufficient_privilege then denied:=true;end;perform pg_temp.graph_assert(denied,'weights require current owner/manager membership');
 denied:=false;begin perform public.get_recommendation_context(null,null);exception when insufficient_privilege then denied:=true;end;perform pg_temp.graph_assert(denied,'invalid mode rejected');
 payload:=jsonb_build_array(jsonb_build_object('key',rid,'source','vacancy','weight',5));perform public.graph_requirement_weights(pid,payload);
 s:=public.graph_requirement_weights(pid);
 perform pg_temp.graph_assert(exists(select 1 from jsonb_array_elements(s->'vacancies') v,jsonb_array_elements(v->'requirements') r where r->>'key'=rid::text and (r->>'weight')::int=5),'weight 5 saved in existing link');
 denied:=false;begin perform public.graph_requirement_weights(pid,jsonb_build_array(jsonb_build_object('key',rid,'source','vacancy','weight',6)));exception when check_violation then denied:=true;end;perform pg_temp.graph_assert(denied,'weight 6 rejected');
 denied:=false;begin perform public.graph_requirement_weights(pid,jsonb_build_array(jsonb_build_object('key',rid,'weight',3)));exception when check_violation then denied:=true;end;perform pg_temp.graph_assert(denied,'missing source rejected');
 denied:=false;begin perform recommendation_private.concepts('skill',b,array['JS']);exception when insufficient_privilege then denied:=true;end;perform pg_temp.graph_assert(denied,'internal canonical resolver cannot be called by clients');
 execute 'reset role';
 -- Editing the same vacancy/catalog must preserve the weight through replace_refs.
 update public.project_vacancies set skills=array['JS'] where id=vid;
 select peso into weight from public.conceitos_vinculos where id=rid;perform pg_temp.graph_assert(weight=5,'unrelated legacy edit preserves weight');
 insert into public.graph_preferences(user_id,share_connections)values(b,true),(c,true);
 perform set_config('request.jwt.claim.sub',a::text,true);execute 'set local role authenticated';
 s:=public.get_recommendation_context('friends');perform pg_temp.graph_assert(jsonb_array_length(s->'friends')=2,'only mutually consented accepted edges become available');
 execute 'reset role';update public.graph_preferences set share_connections=false where user_id=c;
 execute 'set local role authenticated';s:=public.get_recommendation_context('friends');perform pg_temp.graph_assert(jsonb_array_length(s->'friends')=0,'revocation affects the next request, no cached graph');
 perform set_config('request.jwt.claim.sub',b::text,true);
 denied:=false;begin perform public.graph_requirement_weights(pid,payload);exception when insufficient_privilege then denied:=true;end;perform pg_temp.graph_assert(denied,'ordinary candidate cannot edit project weights');
 execute 'reset role';execute 'set local role anon';
 denied:=false;begin perform public.get_recommendation_context('friends');exception when insufficient_privilege then denied:=true;end;perform pg_temp.graph_assert(denied,'anonymous graph context denied');
 execute 'reset role';
end $$;
select 'graph security, opt-in privacy, weight persistence and access tests passed' result;
rollback;
